TLM.f("Sancti/07-05",{"officium":"S. Antonii Mariæ Zaccaria Confessoris","rule":["Gloria"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"1 Cor 2:4"},{"k":"text","la":"Sermo meus et prædicátio mea non in persuasibílibus humánæ sapiéntiæ verbis, sed in ostensióne spíritus et virtútis."},{"k":"ref","la":"Ps 110:1"},{"k":"text","la":"Confitébor tibi, Dómine, in toto corde meo, in consílio justórum et congregatióne."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sermo meus et prædicátio mea non in persuasibílibus humánæ sapiéntiæ verbis, sed in ostensióne spíritus et virtútis."}],"Oratio":[{"k":"text","la":"Fac nos, Dómine Deus, supereminéntem Jesu Christi sciéntiam, spíritu Pauli Apóstoli, edíscere: qua beátus Antónius María mirabíliter erudítus, novas in Ecclésia tua clericórum et vírginum famílias congregávit."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"1. Tim 4:8-16"},{"k":"text","la":"Caríssime: Píetas ad ómnia utilis est: promissiónem habens vitæ, quæ nunc est, et futúræ. Fidélis sermo et omni acceptióne dignus. In hoc enim laborámus et maledícimur, quia sperámus in Deum vivum, qui est Salvátor ómnium hóminum, maxime fidélium. Præcipe hæc et doce. Nemo adolescentiam tuam contémnat: sed exémplum esto fidélium in verbo, in conversatióne, in caritáte, in fide, in castitáte. Dum vénio, atténde lectióni, exhortatióni et doctrínæ. Noli neglégere grátiam, quæ in te est, quæ data est tibi per prophetíam, cum impositióne mánuum presbytérii. Hæc meditáre, in his esto: ut proféctus tuus maniféstus sit ómnibus. Attende tibi et doctrínæ: insta in illis. Hoc enim fáciens, et teípsum salvum fácies, et eos qui te áudiunt."}],"Graduale":[{"k":"ref","la":"Philipp 1:8-9"},{"k":"text","la":"Testis mihi est Deus, quo modo cúpiam omnes vos in viscéribus Jesu Christi. Et hoc oro, ut cáritas vestra magis ac magis abúndet in sciéntia et in omni sensu."},{"k":"ref","la":"Philip 1:10"},{"k":"text","la":"Ut probétis potióra, ut sitis sincéri et sine offénsa in diem Christi."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Philip 1:11"},{"k":"text","la":"Repléti fructu justítiæ per Jesum Christum, in glóriam et laudem Dei. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"2 Cor 7:4"},{"k":"text","la":"Replétus sum consolatióne, superabúndo gáudio in omni tribulatióne nostra. Allelúja."},{"k":"ref","la":"2 Cor 6:13"},{"k":"text","la":"Tamquam fíliis dico: dilatámini et vos. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"2 Cor 10:17-18"},{"k":"text","la":"Qui gloriátur, in Dómino gloriétur: non enim, qui seípsum comméndat, ille probátus est: sed quem Deus comméndat."},{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."},{"k":"ref","la":"Philipp 1:21"},{"k":"text","la":"Mihi vívere Christus est, et mori lucrum."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum"},{"k":"ref","la":"Marc 10:15-21"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Quisquis non recéperit regnum Dei velut párvulus, non intrábit in illud. Et compléxans párvulos et impónens manus super illos, benedicébat eos. Et cum egréssus esset in viam, procúrrens quidam, genu flexo ante eum, rogábat eum: Magíster bone, quid fáciam, ut vitam ætérnam percípiam? Jesus autem dixit ei: Quid me dicis bonum? Nemo bonus, nisi unus Deus. Præcépta nosti: Ne adúlteres, ne occídas, ne furéris, ne falsum testimónium díxeris, ne fraudem féceris, honora patrem tuum et matrem. At ille respóndens, ait illi: Magíster, hæc ómnia observávi a juventúte mea. Jesus autem intúitus eum, diléxit eum et dixit ei: Unum tibi deest: vade, quæcúmque habes, vende et da paupéribus, et habébis thesáurum in cælo: et veni, séquere me."}],"Offertorium":[{"k":"ref","la":"Ps 137:1-2"},{"k":"text","la":"In conspéctu Angelórum psallam tibi: adorábo ad templum sanctum tuum, et confitébor nómini tuo."}],"Secreta":[{"k":"text","la":"Ad mensam cœléstis convívii fac nos, Dómine, eam mentis et córporis puritátem afférre, qua beátus Antónius María, hanc sacratíssimam hóstiam ófferens, mirífice ornátus enítuit."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Philipp 3:17"},{"k":"text","la":"Imitatóres mei estóte, fratres, et observáte eos, qui ita ámbulant, sicut habétis formam nostram."}],"Postcommunio":[{"k":"text","la":"Cœlésti dape, qua pasti sumus, Dómine Jesu Christe, eo corda nostra caritátis igne flamméscant: quo beátus Antónius María salutáris hóstiæ vexíllum, contra Ecclésiæ tuæ hostes, éxtulit ad victóriam:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"b00f6ba46b2d3a5b":{"t":"1 Kor 2, 4, Ps 110, 1\n[u Radićevom prijevodu Rimskog misala 5. Srpnja se slave sv. Ćiril i Metoda koji su u općem kalendaru 7. srpnja] (1 Kor 2, 4) [Šarić, obnovljeno izdanje] Govor moj i propovijedanje moje nije bilo u uvjerljivim riječima ljudske mudrosti, nego u dokazivanju Duha i sile. (Ps 110, 1) [Prijevod M.B. prema KS, Šariću i Douai-Rheims] Hvalit ću te Gospodine, iz svega srca u zboru pravednika i u zajednici.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(1 Kor 2, 4) Govor moj i propovijedanje moje nije bilo u uvjerljivim riječima ljudske mudrosti, nego u dokazivanju Duha i sile."},"5a87a1eef4edf8df":{"t":"<i>Pomolimo se</i>.\n[prijevod M.B. ] Učini, Gospodine Bože, da, u duhu Pavla Apostola, usvojimo nadvisujuće poznavanje Isusa Krista, po kojemu je čudesno poučeni blaženi Antun Marija, okupio u tvojoj crkvi nove obitelji redovnika i djevica.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a1665b0e023454fa":{"t":"1 Tim 4, 8-16\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, pobožnost je svemu korisna jer joj je obećan život - sadašnji i budući. Vjerodostojna je to riječ i vrijedna da se posve prihvati. Ta za to se trudimo i borimo jer se pouzdajemo u Boga živoga koji je Spasitelj svih ljudi, ponajviše vjernika. Zapovijedaj to i naučavaj! Nitko neka ne prezire tvoje mladosti, nego budi uzor vjernicima u riječi, u vladanju, u ljubavi, u vjeri, u čistoći. Dok ne dođem, posveti se čitanju, poticanju, poučavanju. Ne zanemari milosnog dara koji je u tebi, koji ti je dan po proroštvu zajedno s polaganjem ruku starješinstva. Oko toga nastoj, sav u tom budi da tvoj napredak bude svima očit. Pripazi na samog sebe i na poučavanje! Ustraj u tome! Jer to vršeći, spasit ćeš i sebe i one koji te slušaju."},"37e7a9006356f141":{"t":"Fil 1, 8-9, Fil 1, 10\n[prema KS] (Fil 1, 8-9) Bog mi je doista svjedok koliko žudim za svima vama srcem Isusa Krista! I molim za ovo: da ljubav vaša sve više i više raste u spoznanju i potpunu pronicanju (Fil 1, 10) Da mognete prosuditi što je najbolje da budete čisti i besprijekorni za Dan Kristov.\n\nFil 1, 11\n<i>Aleluja</i>, <i>aleluja</i>.\n[prema KS] Puni ploda pravednosti po Isusu Kristu na slavu i hvalu Božju. <i>Aleluja</i>."},"80d306181309c1e0":{"t":"Mk 10, 15-21\nSlijedi sveto Evanđelje po Marku. U ono vrijeme reče Isus svojim učenicima: Tko ne primi Božjega kraljevstva kao dijete ne će uči u njega. I grleći ih i postavljajući na njih ruke blagoslivljao ih je. Kada je pošao dalje, netko pritrči, klekne preda nj i upita ga: Dobri učitelju, što mi je činiti da zadobijem vječni život? Isus mu reče: Što me zoveš dobrim? Nitko nije dobar nego jedini Bog, Poznaš zapovijedi: Ne čini preljuba, ne ubij, ne kradi, ne svjedoči lažno, ne varaj, poštuj svojega oca i majku. A onaj mu odgovori: Učitelju, sve sam to obdržavao od svoje mladosti. Isus ga pogleda, zavoli i reče mu: Jedno ti još treba: Pođi, prodaj sve što imaš, podijeli siromasima i steći ćeš blago na nebu. Tada dođi i hajde za mnom.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.99)"},"ba78220271f9740f":{"t":"Ps 137, 1-2\nPjevam ti pred licem anđela, klanjam se u svetom hramu tvojemu i slavim ime tvoje. Gospodine."},"1abcf84359b92cc8":{"t":"[prijevod M.B.] Daj, Gospodine, da za stol nebeske gozbe donesemo onakvu čistoću duha i tijela,po kojoj je blaženi Antun Marija zasjao divno ukrašen prinoseći ovu presvetu žrtvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"dfe8a210d9407a4f":{"t":"Fil 3, 17\nUgledajte se u mene i vladajte se prema onima koji žive po primjeru koji vam mi dajemo."},"2dbc21c53e851781":{"t":"<i>Pomolimo se</i>.\n[prijevod M.B.] Gospodine Isuse Kriste, neka se po nebeskoj gozbi kojom smo nahranjeni naša srca upale onakvom vatrom ljubavi po kojoj je blaženi Antun Marija stijeg spasonosne žrtve doveo do pobjede protiv neprijatelja Crkve:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
